package br.com.saferoute;
import org.springframework.context.annotation.Configuration;import org.springframework.beans.factory.annotation.Value;import org.springframework.web.servlet.config.annotation.*;import org.springframework.web.servlet.HandlerInterceptor;import jakarta.servlet.http.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;
@Configuration public class ApiAccess implements WebMvcConfigurer {
 private final String key;public ApiAccess(@Value("${saferoute.admin-key}") String key){if(key.length()<16)throw new IllegalArgumentException("ADMIN_API_KEY requer no mínimo 16 caracteres");this.key=key;}
 @Override public void addInterceptors(InterceptorRegistry registry){registry.addInterceptor(new HandlerInterceptor(){@Override public boolean preHandle(HttpServletRequest req,HttpServletResponse res,Object handler)throws Exception{if(req.getMethod().equals("GET")||req.getRequestURI().equals("/api/routes"))return true;String got=req.getHeader("X-Admin-Key");if(got!=null&&MessageDigest.isEqual(got.getBytes(StandardCharsets.UTF_8),key.getBytes(StandardCharsets.UTF_8)))return true;res.setStatus(401);res.setContentType("application/json;charset=UTF-8");res.getWriter().write("{\"status\":401,\"message\":\"Chave de operador ausente ou inválida\"}");return false;}}).addPathPatterns("/api/**");}
}
